"""Controlled Pytest test suite generated by AI API Testing Agent."""

import pytest
import httpx

BASE_URL = "http://127.0.0.1:8899"

def test_tc_001_get_api_users_positive():
    """[TC-001] GET /api/users | Scenario: positive
    List all users
    """
    url = f"{BASE_URL}/api/users"
    response = httpx.get(url, timeout=10.0, params={'limit': 10})
    assert response.status_code == 200, f'Expected 200, got {response.status_code}: {response.text}'

def test_tc_002_post_api_users_positive():
    """[TC-002] POST /api/users | Scenario: positive
    Create user
    """
    url = f"{BASE_URL}/api/users"
    response = httpx.post(url, timeout=10.0, json={'username': 'alice_smith', 'email': 'alice.smith@example.com', 'role': 'admin'})
    assert response.status_code == 201, f'Expected 201, got {response.status_code}: {response.text}'

